package com.ganesh.drycleaning.service;
import com.ganesh.drycleaning.dto.PickupInput;import com.ganesh.drycleaning.entity.*;import com.ganesh.drycleaning.repository.*;import com.ganesh.drycleaning.exception.NotFoundException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDate;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class PickupServiceTest {
 @Mock PickupRequestRepository repository;@Mock ServiceItemRepository items;@Mock org.springframework.context.ApplicationEventPublisher events;@InjectMocks PickupService service;
 @Test void createsNewRequest(){ServiceItem s=new ServiceItem();s.setName("Simple Ironing");when(items.findAll()).thenReturn(List.of(s));when(repository.save(any())).thenAnswer(i->i.getArgument(0));var in=new PickupInput("Test","1234567890","","Test address","Simple Ironing",LocalDate.now().plusDays(1),"Morning","");var p=service.create(in);assertEquals(PickupStatus.NEW,p.getStatus());assertEquals("Test",p.getName());assertNotNull(p.getCreatedAt());verify(repository).save(p);verify(events).publishEvent(new PickupCreatedEvent(p.getId()));}
 @Test void changesStatus(){PickupRequest p=new PickupRequest();when(repository.findById(1L)).thenReturn(Optional.of(p));when(repository.save(p)).thenReturn(p);assertEquals(PickupStatus.CONFIRMED,service.updateStatus(1L,PickupStatus.CONFIRMED).getStatus());}
 @Test void missingPickupThrows(){when(repository.findById(99L)).thenReturn(Optional.empty());assertThrows(NotFoundException.class,()->service.updateStatus(99L,PickupStatus.CANCELLED));}
 @Test void rejectsUnknownService(){when(items.findAll()).thenReturn(List.of());assertThrows(IllegalArgumentException.class,()->service.create(new PickupInput("Test","1234567890","","Address","Unknown",LocalDate.now(),"Morning","")));verifyNoInteractions(repository);}
}